function parseISODate(value) {
  if (typeof value !== 'string' || !ISO_DATE_RE.test(value)) {
    throw new Error('Invalid date format: expected ISO date YYYY-MM-DD');
  }
  const [y, m, d] = value.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (
    dt.getUTCFullYear() !== y ||
    dt.getUTCMonth() !== m - 1 ||
    dt.getUTCDate() !== d
  ) {
    throw new Error('Invalid date: ' + value);
  }
  return dt;
}

function salesReport(args) {
  const start = parseISODate(args.start_date);
  const end = parseISODate(args.end_date);
  if (start > end) {
    throw new Error('start_date must not be after end_date');
  }
  let total = 0;
  let count = 0;
  for (const row of sales) {
    const d = parseISODate(row.date);
    if (d >= start && d <= end) {
      total += row.amount;
      count += 1;
    }
  }
  return {
    content: [
      {
        type: 'text',
        text: `total: ${total}\ncount: ${count}`,
      },
    ],
  };
